import{_ as e,o as r,c as o,a3 as i}from"./chunks/framework.BwzYn71E.js";const u=JSON.parse('{"title":"基础基建原理","description":"","frontmatter":{"translationSource":{"title":"基础基建原理","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=8XrtahEh9tfuCux72hbfbI","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/basic-factory-principles"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/basic-factory-principles"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/basic-factory-principles"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/basic-factory-principles"}]]},"headers":[],"relativePath":"zh/basic-factory-principles.md","filePath":"zh/page-8XrtahEh9tfuCux72hbfbI.md"}'),t={name:"zh/basic-factory-principles.md"};function n(s,a,l,h,p,c){return r(),o("div",null,[...a[0]||(a[0]=[i('<div class="logistics-content"><h1 id="基础基建原理" tabindex="-1">基础基建原理 <a class="header-anchor" href="#基础基建原理" aria-label="Permalink to &quot;基础基建原理&quot;">​</a></h1><blockquote><p>源页面 ID：<code>8XrtahEh9tfuCux72hbfbI</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=8XrtahEh9tfuCux72hbfbI" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span class="mark-red"><strong>十分严重的缺乏维护，应当讨论该子页面下目录是否合理</strong></span></p><p><span id="source-block-y7NDBIgu8isDQOXArHWW0Q"></span></p><h2 id="分流器和汇流器" tabindex="-1">分流器和汇流器 <a class="header-anchor" href="#分流器和汇流器" aria-label="Permalink to &quot;分流器和汇流器&quot;">​</a></h2><p><span id="source-block-RPB2hRULTNApMTg45UlSNN"></span></p><h2 id="设备的相位、轮询、阻塞" tabindex="-1">设备的相位、轮询、阻塞 <a class="header-anchor" href="#设备的相位、轮询、阻塞" aria-label="Permalink to &quot;设备的相位、轮询、阻塞&quot;">​</a></h2><p><span id="source-block-Oyx2mq8lNIlhIsxtNOwBM3"></span></p><h2 id="存取线和准入口" tabindex="-1">存取线和准入口 <a class="header-anchor" href="#存取线和准入口" aria-label="Permalink to &quot;存取线和准入口&quot;">​</a></h2><p><span id="source-block-NfGiRGZYbKjdrZcmwSyDsI"></span></p><h2 id="协议存储箱" tabindex="-1">协议存储箱 <a class="header-anchor" href="#协议存储箱" aria-label="Permalink to &quot;协议存储箱&quot;">​</a></h2><p><span id="source-block-arv2ggXGKHsuEaiL0kZg6V"></span></p><h2 id="有理分流理论" tabindex="-1">有理分流理论 <a class="header-anchor" href="#有理分流理论" aria-label="Permalink to &quot;有理分流理论&quot;">​</a></h2><p><span id="source-block-BMLkM2k9r6btZFG3eDCRf9"></span></p><h3 id="内部流通的有理分流器" tabindex="-1">内部流通的有理分流器 <a class="header-anchor" href="#内部流通的有理分流器" aria-label="Permalink to &quot;内部流通的有理分流器&quot;">​</a></h3><p><span id="source-block-o4ulMUVo12T2A11pLRJzar"></span></p><h3 id="内部阻塞的有理分流器" tabindex="-1">内部阻塞的有理分流器 <a class="header-anchor" href="#内部阻塞的有理分流器" aria-label="Permalink to &quot;内部阻塞的有理分流器&quot;">​</a></h3><p><span id="source-block-8AivCxQKTZlqERyOXW5EuV"></span></p><h3 id="pwm震荡热能池" tabindex="-1">PWM震荡热能池 <a class="header-anchor" href="#pwm震荡热能池" aria-label="Permalink to &quot;PWM震荡热能池&quot;">​</a></h3><p><span id="source-block-t9kjUHPVcj7vEOmLBvKnqD"></span></p><h2 id="优先级和溢流器" tabindex="-1">优先级和溢流器 <a class="header-anchor" href="#优先级和溢流器" aria-label="Permalink to &quot;优先级和溢流器&quot;">​</a></h2><p><span id="source-block-EHhBNcPi9z2GuxnXC3X587"></span></p><h3 id="逻辑与、逻辑或、逻辑非" tabindex="-1">逻辑与、逻辑或、逻辑非 <a class="header-anchor" href="#逻辑与、逻辑或、逻辑非" aria-label="Permalink to &quot;逻辑与、逻辑或、逻辑非&quot;">​</a></h3><p><span id="source-block-Us53G6Fq1qOnAB1JtpfakN"></span></p><h2 id="混带与混产" tabindex="-1">混带与混产 <a class="header-anchor" href="#混带与混产" aria-label="Permalink to &quot;混带与混产&quot;">​</a></h2><p><span id="source-block-a21wIHI7kMBJ062ZfbKwEi"></span></p><h2 id="环带时钟与沙漏时钟" tabindex="-1">环带时钟与沙漏时钟 <a class="header-anchor" href="#环带时钟与沙漏时钟" aria-label="Permalink to &quot;环带时钟与沙漏时钟&quot;">​</a></h2><p><span id="source-block-spGnfPdSVraF0np58q6Ptz"></span></p><h2 id="限流理论和长周期固体钟" tabindex="-1">限流理论和长周期固体钟 <a class="header-anchor" href="#限流理论和长周期固体钟" aria-label="Permalink to &quot;限流理论和长周期固体钟&quot;">​</a></h2><p><span id="source-block-wWuTRL4v4083J95sW5rdD2"></span></p><h3 id="内部流通的有理限流器" tabindex="-1">内部流通的有理限流器 <a class="header-anchor" href="#内部流通的有理限流器" aria-label="Permalink to &quot;内部流通的有理限流器&quot;">​</a></h3><p><span id="source-block-7R9931VccE38fQGWecdJ9R"></span></p><h3 id="内部阻塞的有理限流器" tabindex="-1">内部阻塞的有理限流器 <a class="header-anchor" href="#内部阻塞的有理限流器" aria-label="Permalink to &quot;内部阻塞的有理限流器&quot;">​</a></h3><p><span id="source-block-63Gw6YCT379UUsIxenCJ8A"></span></p><h3 id="更复杂的物流体系" tabindex="-1">更复杂的物流体系 <a class="header-anchor" href="#更复杂的物流体系" aria-label="Permalink to &quot;更复杂的物流体系&quot;">​</a></h3><p><span id="source-block-2gXeYhYCoCuC01GqBfv0VH"></span></p><h2 id="蓝图的摆放顺序" tabindex="-1">蓝图的摆放顺序 <a class="header-anchor" href="#蓝图的摆放顺序" aria-label="Permalink to &quot;蓝图的摆放顺序&quot;">​</a></h2><p><span id="source-block-BHghb30fhpQwUubFd4QLFG"></span></p><h2 id="液气理论" tabindex="-1">液气理论 <a class="header-anchor" href="#液气理论" aria-label="Permalink to &quot;液气理论&quot;">​</a></h2><p><span id="source-block-2B8Pu0ql6WXlq0qYbqukuu"></span></p><h3 id="液体钟" tabindex="-1">液体钟 <a class="header-anchor" href="#液体钟" aria-label="Permalink to &quot;液体钟&quot;">​</a></h3><p><span id="source-block-7YPti9NugqqBqRBS2crZup"></span></p><h2 id="反应池与固液转换" tabindex="-1">反应池与固液转换 <a class="header-anchor" href="#反应池与固液转换" aria-label="Permalink to &quot;反应池与固液转换&quot;">​</a></h2><p><span id="source-block-OhinWjoGtZso7YKb0WOuPR"></span></p><h4 id="多输入同时发生反应" tabindex="-1">多输入同时发生反应 <a class="header-anchor" href="#多输入同时发生反应" aria-label="Permalink to &quot;多输入同时发生反应&quot;">​</a></h4><p>反应池存在虚拟槽位，可以虚空存物。使用杂物阻塞扩容反应池比反应池多的槽位后，两者表现依旧不同，扩容反应池不会因为反应池相同的反应而阻塞，疑似虚拟槽位更多。</p><p><span id="source-block-CdxP4h4o7oRy9BvXZllz0N"></span></p><h4 id="类溢流器作用" tabindex="-1">类溢流器作用 <a class="header-anchor" href="#类溢流器作用" aria-label="Permalink to &quot;类溢流器作用&quot;">​</a></h4><p>反应池内的物质优先输出而非反应。</p><p><span id="source-block-50kXQ9bZCiVAPpHStZsrQx"></span></p><h4 id="输入输出特性" tabindex="-1">输入输出特性 <a class="header-anchor" href="#输入输出特性" aria-label="Permalink to &quot;输入输出特性&quot;">​</a></h4><p>物品输入输出均总是轮询，即不会变成优先级。液体输出若两个口为同一液体，总是轮询。液体输入总是优先级，先连接先输入。物品除了反应得到的液化息壤，其余全部优先输出。</p><p><span id="source-block-q7XChR42dU2AHd344rmzCq"></span></p><h4 id="物流桥代替" tabindex="-1">物流桥代替 <a class="header-anchor" href="#物流桥代替" aria-label="Permalink to &quot;物流桥代替&quot;">​</a></h4><p>这一点通常被称为透传，即同一物品可以从中输入并输出，在一定程度上相当于传送带穿过反应池。</p><p><span id="source-block-YUOFdiSzwhnfEAfYwn52LM"></span></p><h4 id="开关时的不同" tabindex="-1">开关时的不同 <a class="header-anchor" href="#开关时的不同" aria-label="Permalink to &quot;开关时的不同&quot;">​</a></h4><p>反应池有三种状态</p><p>关闭（已关闭）：物品能流入不能流出，不会反应</p><p>待机（未通电）：物品自由流入流出，不会反应</p><p>工作（空闲/生产）：物品自由流入流出，会反应</p><p>类似的，取货口也有关闭与非关闭的区别</p><p><span id="source-block-9RG2JmGnEOHhTuIk2KhEKD"></span></p><h2 id="多口暗管" tabindex="-1">多口暗管 <a class="header-anchor" href="#多口暗管" aria-label="Permalink to &quot;多口暗管&quot;">​</a></h2><p><span id="source-block-JGymO4oX6mnI3uYZuKrZKx"></span></p><h2 id="固气转换、气液转换" tabindex="-1">固气转换、气液转换 <a class="header-anchor" href="#固气转换、气液转换" aria-label="Permalink to &quot;固气转换、气液转换&quot;">​</a></h2><p><span id="source-block-QD2hr2daemWzS8eUkzxFES"></span></p><h3 id="简易自适应" tabindex="-1">简易自适应 <a class="header-anchor" href="#简易自适应" aria-label="Permalink to &quot;简易自适应&quot;">​</a></h3></div>',1)])])}const b=e(t,[["render",n]]);export{u as __pageData,b as default};
